// Audit signing + verification (master prompt §5/§6).
// Ed25519 over the UTF-8 bytes of the row's record_hash hex string.
// Signatures land in audit_signatures; public keys in audit_keys.
// Private key comes from env AUDIT_SIGNING_PRIVATE_KEY (base64 DER PKCS#8,
// generated by scripts/gen-audit-key.ts). Never log or commit it.
import {
  createHash,
  createPrivateKey,
  createPublicKey,
  sign,
  verify,
} from "node:crypto";
import { createAdminClient } from "@/lib/supabase/admin";
import { callDbFunction } from "@/lib/supabase/rpc";

export function auditKeyId(): string {
  return process.env.AUDIT_KEY_ID ?? "audit-2026-01";
}

/** SHA-256 fingerprint of a public key (base64 DER SPKI). */
export function publicKeyFingerprint(publicKeyB64: string): string {
  return createHash("sha256")
    .update(Buffer.from(publicKeyB64, "base64"))
    .digest("hex");
}

export function signRecordHash(recordHash: string, privateKeyB64: string): string {
  const key = createPrivateKey({
    key: Buffer.from(privateKeyB64, "base64"),
    format: "der",
    type: "pkcs8",
  });
  return sign(null, Buffer.from(recordHash, "utf8"), key).toString("base64");
}

export function verifyRecordHash(
  recordHash: string,
  signatureB64: string,
  publicKeyB64: string,
): boolean {
  try {
    const pub = createPublicKey({
      key: Buffer.from(publicKeyB64, "base64"),
      format: "der",
      type: "spki",
    });
    return verify(
      null,
      Buffer.from(recordHash, "utf8"),
      pub,
      Buffer.from(signatureB64, "base64"),
    );
  } catch {
    return false;
  }
}

/** Sign every audit_log row that has no signature yet. Returns how many
 * rows were signed. Throws if the signing key is not configured. */
export async function signAuditRows(): Promise<{ signed: number }> {
  const privateKey = process.env.AUDIT_SIGNING_PRIVATE_KEY;
  if (!privateKey) throw new Error("AUDIT_SIGNING_PRIVATE_KEY is not set");
  const admin = createAdminClient();
  const { data: rows, error } = await admin
    .from("audit_log")
    .select("seq,record_hash")
    .order("seq", { ascending: false })
    .limit(500);
  if (error) throw new Error(error.message);
  const { data: sigs } = await admin
    .from("audit_signatures")
    .select("audit_seq");
  const signedSeqs = new Set((sigs ?? []).map((s) => s.audit_seq));
  const pending = (rows ?? []).filter((r) => !signedSeqs.has(r.seq));
  if (pending.length === 0) return { signed: 0 };
  const keyId = auditKeyId();
  const inserts = pending.map((r) => ({
    audit_seq: r.seq,
    key_id: keyId,
    signature: signRecordHash(r.record_hash, privateKey),
  }));
  const { error: insErr } = await admin
    .from("audit_signatures")
    .insert(inserts as never);
  if (insErr) throw new Error(insErr.message);
  return { signed: inserts.length };
}

export interface SignatureCheck {
  ok: boolean;
  present: boolean;
  keyId: string | null;
  fingerprint: string | null;
  signature: string | null;
  signedAt: string | null;
  validFrom: string | null;
  validTo: string | null;
}

export async function verifyAuditSignature(seq: number): Promise<SignatureCheck> {
  const empty: SignatureCheck = {
    ok: false,
    present: false,
    keyId: null,
    fingerprint: null,
    signature: null,
    signedAt: null,
    validFrom: null,
    validTo: null,
  };
  const admin = createAdminClient();
  const { data: sig } = await admin
    .from("audit_signatures")
    .select("*")
    .eq("audit_seq", seq)
    .maybeSingle();
  if (!sig) return empty;
  const { data: key } = await admin
    .from("audit_keys")
    .select("*")
    .eq("key_id", sig.key_id)
    .maybeSingle();
  const { data: row } = await admin
    .from("audit_log")
    .select("record_hash")
    .eq("seq", seq)
    .maybeSingle();
  if (!key || !row) {
    return { ...empty, present: true, keyId: sig.key_id, signature: sig.signature, signedAt: sig.signed_at };
  }
  const ok = verifyRecordHash(row.record_hash, sig.signature, key.public_key);
  return {
    ok,
    present: true,
    keyId: sig.key_id,
    fingerprint: key.fingerprint,
    signature: sig.signature,
    signedAt: sig.signed_at,
    validFrom: key.valid_from,
    validTo: key.valid_to,
  };
}

export interface AuditRowVerification {
  found: boolean;
  hash_ok: boolean;
  prev_ok: boolean;
  record_hash: string;
  prev_hash: string;
  signature: SignatureCheck;
}

/** Full verification of one audit row: hash chain (via verify_audit) +
 * Ed25519 signature. */
export async function verifyAuditRow(seq: number): Promise<AuditRowVerification> {
  const hash = await callDbFunction<{
    found: boolean;
    hash_ok: boolean;
    prev_ok: boolean;
    record_hash: string;
    prev_hash: string;
  }>(createAdminClient(), "verify_audit", { p_seq: seq });
  const signature = await verifyAuditSignature(seq);
  return { ...hash, signature };
}
